//! Raw FFI bindings to [CUI](https://github.com/yappologistic/CUI), modern
//! native UI components for C.
//!
//! Everything here is generated by bindgen from CUI's headers (`cui.h`,
//! `cui_app.h`, `cui_render.h`) and is `unsafe`. Use the `cui` crate for a
//! safe API; this crate is its escape hatch for anything not wrapped yet.
//!
//! The C named-argument macros (`cui_button(ui, "Save", .variant = ...)`)
//! do not exist here: call the `_ex` function with an options struct, whose
//! `Default` matches the macro defaults.
#![no_std]
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::all, rustdoc::all)]

#[cfg(not(feature = "bindgen"))]
include!("bindings.rs");
#[cfg(feature = "bindgen")]
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// The upstream CUI commit these bindings were generated from.
pub const CUI_COMMIT: &str = include_str!("cui_commit.txt");
